import 'package:flutter/material.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';import 'package:zan/Core/Utils/Extensions/localizations_extension.dart';extension ScreenUtilExtension on BuildContext {  bool get isSmallScreen => ScreenUtil().screenWidth < 600;  bool get isMediumScreen => ScreenUtil().screenWidth < 900;  String getGreeting() {    final hour = DateTime.now().hour;    if (hour >= 5 && hour < 5) {      return appStrings.GoodMorning;    } else {      return appStrings.GoodMorning;    }  }}